def adjust_values(dct, key, target_ratio):
    if key not in dct:
        raise KeyError(f"{key} not found in the dictionary")

    total_magnitude = sum(dct.values())
    target_remaining_magnitude = dct[key] / target_ratio - dct[key]

    remaining_magnitude = total_magnitude - dct[key]
    scale_factor = target_remaining_magnitude / remaining_magnitude
    adjusted_dct = {}

    for k, v in dct.items():
        if k == key:
            adjusted_dct[k] = dct[key]
        else:
            adjusted_dct[k] = v * scale_factor

    return adjusted_dct

