```R
# Function to calculate the power of a negative binomial regression
calc_power <- function(n, effect_size, alpha) {
  z_alpha <- qnorm(1 - alpha)
  z_beta <- qnorm(power)
  lambda <- effect_size * sqrt(n)

  p_power <- pnorm(z_alpha - lambda) + pnorm(-z_alpha - lambda)
  return(p_power)
}

# Function to find the sample size that achieves the desired power
find_sample_size <- function(effect_size, alpha, power, max_n = 100000) {
  for (n in 1:max_n) {
    if (calc_power(n, effect_size, alpha) >= power) {
      return(n)
    }
  }
  return(max_n)
}

# Set parameters for the negative binomial regression
