Now, you can implement the function as follows:
```typescript
import { Interval, isWithinInterval, differenceInMilliseconds } from 'date-fns';
import { PassOffering, RecurrenceRule } from './your-models-file';
import { RRule, RRuleSet } from 'rrule';

interface ApplicablePass {
  passId: string;
  pass: PassOffering;
  durationCovered: number;
}

function findApplicablePasses(
  uncoveredIntervals: Interval[],
  passes: Map<string, PassOffering>,
): ApplicablePass[] {
  const applicablePasses: ApplicablePass[] = [];

  passes.forEach((pass, passId) => {
    if (pass.status !== EntityStatus.ACTIVE) {
      return;
    }

    let totalDurationCovered = 0;

    uncoveredIntervals.forEach((uncoveredInterval) => {
      pass.rules.forEach((rule) => {
        const ruleSet = new RRuleSet();

        const rrule = RRule.fromString(rule.recurrence);
        ruleSet.rrule(rrule);

        const ruleStartDates = ruleSet.between(
          uncoveredInterval.start,
          uncoveredInterval.end,
          true,
        );

        ruleStartDates.forEach((startDate) => {
          const endDate = rrule.options.until;

          if (
            rule.enter &&
            !isWithinInterval(startDate, {
              start: add(startDate, rule.enter.after),
              end: add(startDate, rule.enter.before),
            })
          ) {
            return;
          }

          if (
            rule.exit &&
            !isWithinInterval(endDate, {
              start: add(endDate, rule.exit.after),
              end: add(endDate, rule.exit.before),
            })
          ) {
            return;
          }

          const passInterval: Interval = { start: startDate, end: endDate };
          const intersection = interval.intersection(
            uncoveredInterval,
            passInterval,
          );

          if (intersection) {
            totalDurationCovered += differenceInMilliseconds(
              intersection.start,
              intersection.end,
            );
          }
        });
      });
    });

    if (totalDurationCovered > 0) {
      applicablePasses.push({
        passId,
        pass,
        durationCovered: totalDurationCovered,
      });
    }
  });

  applicablePasses.sort((a, b) => b.durationCovered - a.durationCovered);

  return applicablePasses;
}
```
