import { Interval, isWithinInterval, differenceInMilliseconds } from 'date-fns';
import { PassOffering, PriceWindowResult, RecurrenceRule } from './your-models-file';
import { RRule, RRuleSet } from 'rrule';

function applyBestPass(
  uncoveredIntervals: Interval[],
  passes: Map<string, PassOffering>,
): PriceWindowResult[] {
  const applicablePasses = findApplicablePasses(uncoveredIntervals, passes);

  if (applicablePasses.length === 0) {
    return [];
  }

  const bestPass = applicablePasses[0];
  const coveredIntervals: PriceWindowResult[] = [];

  bestPass.pass.rules.forEach((rule) => {
    const ruleSet = new RRuleSet();

    const rrule = RRule.fromString(rule.recurrence);
    ruleSet.rrule(rrule);

    uncoveredIntervals = uncoveredIntervals.flatMap((uncoveredInterval) => {
      const ruleStartDates = ruleSet.between(
        uncoveredInterval.start,
        uncoveredInterval.end,
        true,
      );

      let remainingUncoveredIntervals: Interval[] = [uncoveredInterval];

      ruleStartDates.forEach((startDate) => {
        const endDate = rrule.options.until;

        if (
          rule.enter &&
          !isWithinInterval(startDate, {
            start: add(startDate, rule.enter.after),
            end: add(startDate, rule.enter.before),
          })
        ) {
          return;
        }

        if (
          rule.exit &&
          !isWithinInterval(endDate, {
            start: add(endDate, rule.exit.after),
            end: add(endDate, rule.exit.before),
          })
        ) {
          return;
        }

        const passInterval: Interval = { start: startDate, end: endDate };
        const intersection = interval.intersection(
          uncoveredInterval,
          passInterval,
        );

        if (intersection) {
          // Create a PriceWindowResult instance for the covered interval
          coveredIntervals.push(new PriceWindowResult({
            startTime: intersection.start,
            endTime: intersection.end,
            source: PriceWindowSource.PASS,
            sourceRef: new VendDocumentReference({
              collection: PassOffering.collectionPath,
              documentId: bestPass.passId,
            }),
            price: 0,
          }));

          // Remove the covered interval from the remaining uncovered intervals
          remainingUncoveredIntervals = remainingUncoveredIntervals.flatMap((interval) => [
            { start: interval.start, end: intersection.start },
            { start: intersection.end, end: interval.end },
          ]);
        }
      });

      return remainingUncoveredIntervals;
    });
  });

  return coveredIntervals;
}
