import React, { createContext, useContext } from 'react';
import { useQuery } from 'react-query';
import { fetchUserProfile } from './api'; // Make sure to implement this function in your API service

const UserContext = createContext();

export const UserProvider = ({ children }) => {
  const userId = '1'; // Replace with a dynamic user ID or a way to get it from your app
  const { data: user, isLoading, isError } = useQuery(['user', userId], () => fetchUserProfile(userId));

  return (
    <UserContext.Provider value={{ user, isLoading, isError }}>
      {children}
    </UserContext.Provider>
  );
};

export const useUser = () => {
  const context = useContext(UserContext);

  if (!context) {
    throw new Error('useUser must be used within a UserProvider');
