```javascript
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

class GameObject {
    constructor(x, y, width, height, color) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.color = color;
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

class Player extends GameObject {
    constructor(x, y) {
        super(x, y, 30, 10, 'white');
    }

    move(direction) {
        if (direction === 'left') {
            this.x -= 5;
        } else if (direction === 'right') {
            this.x += 5;
        }
    }
}

class Invader extends GameObject {
    constructor(x, y) {
        super(x, y, 30, 30, 'lime');
    }
}

const player = new Player(canvas.width / 2 - 15, canvas.height - 30);
const invaders = [];

for (let y = 0; y < 3; y++) {
    for (let x = 0; x < 10; x++) {
        invaders.push(new Invader(70 * x + 60, 50 * y + 40));
    }
}

document.addEventListener('keydown', (e) => {
    if (e.code === 'ArrowLeft') {
        player.move('left');
    } else if (e.code === 'ArrowRight') {
        player.move('right');
    }
});

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    player.draw();
    invaders.forEach(invader => invader.draw());
    requestAnimationFrame(draw);
}

draw();
```
