function searchImageInfo = buildSearchImageInfo(imageFolder, channelToCorrelate)
    % Build table of search image info
    searchImageInfoStruct = dir(fullfile(imageFolder, "*.jpg"));
    searchImageInfo = struct2table(searchImageInfoStruct);
    searchImageInfo = convertvars(searchImageInfo, @iscell, 'string');
    searchImageInfo.Properties.VariableNames{'name'} = 'filename';

    name = extractBefore(searchImageInfo.filename, '.');
    searchImageInfo = addvars(searchImageInfo, name, 'Before', 1);

    imageDS = imageDatastore(fullfile(searchImageInfo.folder, searchImageInfo.filename));
    imageRGB = readall(imageDS);

    image = cellfun(@(x) x(:, :, channelToCorrelate), imageRGB, 'UniformOutput', false);
    searchImageInfo = addvars(searchImageInfo, image, imageRGB, 'After', 1);

    searchImageM = cellfun(@(x) size(x, 1), searchImageInfo.image);
    searchImageN = cellfun(@(x) size(x, 2), searchImageInfo.image);
    searchImageInfo = addvars(searchImageInfo, searchImageM, searchImageN, 'After', 2);
end
