To achieve this, you can use the 'node-jose' library, which offers support for JWE encryption and decryption. You can install it by running `npm install node-jose`.

Here's a sample script that demonstrates how to extract a public key from a Base64 encoded private key, and then encrypt a JWE using RSAES-PKCS1-v1\_5 key encryption and AES\_256\_CBC\_HMAC\_SHA\_512 content encryption:
```javascript
const jose = require('node-jose');
const fs = require('fs');

// Replace with your Base64 encoded private key
const base64PrivateKey = 'your_base64_encoded_private_key_here';
const privateKeyPem = Buffer.from(base64PrivateKey, 'base64').toString('utf-8');

// Replace with the string you want to encrypt
const payload = 'your_string_to_encrypt_here';

(async () => {
  try {
    // Import private key
    const privateKey = await jose.JWK.asKey(privateKeyPem, 'pem');

    // Extract public key from private key
    const publicKey = privateKey.toPublic();

    // Encrypt JWE using public key
    const jwe = await jose.JWE.createEncrypt({
      format: 'compact',
      fields: {
        alg: 'RSA1_5', // RSAES-PKCS1-v1_5 key encryption
        enc: 'A256CBC-HS512' // AES_256_CBC_HMAC_SHA_512 content encryption
      }
    }, publicKey).update(payload).final();

    console.log('Encrypted JWE:', jwe);

  } catch (error) {
    console.error('Error:', error);
  }
})();
```
Make sure you replace `'your_base64_encoded_private_key_here'` with your actual Base64 encoded private key and `'your_string_to_encrypt_here'` with the string you want to encrypt. Run the script using Node.js, and you'll get the encrypted JWE as output.

