<?php

namespace Drupal\csv_import\Controller;

use Drupal\Core\Controller\ControllerBase;
use Drupal\node\Entity\Node;
use Drupal\file\Entity\File;
use Drupal\media\Entity\Media;

class CsvImportController extends ControllerBase {

  public static function import($file_uri) {
    $data = self::parseCsv($file_uri);

    foreach ($data as $row) {
      $title = $row[0];
      $body = $row[1];
      $image_url = $row[2];

      // Look for existing nodes with the same title.
      $query = \Drupal::entityQuery('node')
        ->condition('title', $title)
        ->range(0, 1);
      $nid = $query->execute();

      // If a node is found, update it. Otherwise, create a new one.
      if (!empty($nid)) {
        $node = Node::load(reset($nid));
      } else {
        $node = Node::create(['type' => 'YOUR_CONTENT_TYPE']);
        $node->setTitle($title);
      }

      // Set the body field value.
      $node->set('body', [
        'value' => $body,
        'format' => 'full_html',
      ]);

      // Import the image and set the media field value.
      $image_data = file_get_contents($image_url);
      $image_file = file_save_data($image_data, 'public://' . basename($image_url), FILE_EXISTS_REPLACE);
      $media = Media::create([
        'bundle' => 'YOUR_IMAGE_MEDIA_BUNDLE',
        'field_media_image' => [
          'target_id' => $image_file->id(),
          'alt' => $title,
          'title' => $title,
        ],
      ]);
      $media->setName($title)->setPublished(TRUE)->save();

      // Set the media field value.
      $node->set('YOUR_MEDIA_FIELD_NAME', [
        'target_id' => $media->id(),
      ]);

      // Save the node.
      $node->save();
    }
  }

  private static function parseCsv($file_uri) {
    $data = [];
    if (($handle = fopen($file_uri, 'r')) !== FALSE) {
      while (($row = fgetcsv($handle, 0, ',')) !== FALSE) {
        $data[] = $row;
      }
      fclose($handle);
    }
    return $data;
  }
}
```
Don't forget to replace `'YOUR_CONTENT_TYPE'`, `'YOUR_IMAGE_MEDIA_BUNDLE'`, and `'YOUR_MEDIA_FIELD_NAME'` with the appropriate machine names for your content type, image media bundle, and media field, respectively.

