In Swift, you can use the `FileManager` class to observe file changes and the `DispatchSource` to respond to those changes. Here's an example function that watches a specific file on disk and performs an action when the file is modified:
```swift
import Foundation

func watchFile(for path: String, onChange: @escaping () -> Void) {
    let fileDescriptor = open(path, O_EVTONLY)
    if fileDescriptor == -1 {
        print("Error: Unable to open the file at path '\(path)'.")
        return
    }

    let queue = DispatchQueue(label: "fileWatcherQueue")
    let source = DispatchSource.makeFileSystemObjectSource(fileDescriptor: fileDescriptor, eventMask: .write, queue: queue)

    source.setEventHandler {
        onChange()
    }

    source.setCancelHandler {
        close(fileDescriptor)
    }

    source.resume()
}

// Usage example
