```csharp
using System.Data;
using Dapper;
using MySql.Data.MySqlClient;
using System.Collections.Generic;

public class PLC
{
    public int INDEX_KEY { get; set; }
    public string IP { get; set; }
    public string Name { get; set; }
}

public class PLCService
{
    private readonly string _connectionString;

    public PLCService(string connectionString)
    {
        _connectionString = connectionString;
    }

    private IDbConnection GetConnection()
    {
        return new MySqlConnection(_connectionString);
    }

    public List<PLC> GetAllPLCs()
    {
        using (var connection = GetConnection())
        {
            connection.Open();
            return connection.Query<PLC>("SELECT INDEX_KEY, IP, Name FROM PLC_INFO").AsList();
        }
    }

    public void AddPLC(PLC plc)
    {
        using (var connection = GetConnection())
        {
            connection.Open();
            connection.Execute("INSERT INTO PLC_INFO (IP, Name) VALUES (@IP, @Name)", plc);
        }
    }

    public void UpdatePLC(PLC plc)
    {
        using (var connection = GetConnection())
        {
            connection.Open();
            connection.Execute("UPDATE PLC_INFO SET IP = @IP, Name = @Name WHERE INDEX_KEY = @INDEX_KEY", plc);
        }
    }

    public void DeletePLC(int indexKey)
    {
        using (var connection = GetConnection())
        {
            connection.Open();
            connection.Execute("DELETE FROM PLC_INFO WHERE INDEX_KEY = @INDEX_KEY", new { INDEX_KEY = indexKey });
        }
    }
}
```
In this example, the `PLCService` class has methods to handle the following operations:

1. `GetAllPLCs()`: Fetches all PLC records from the `PLC_INFO` table and returns them as a `List<PLC>`.
2. `AddPLC(PLC plc)`: Inserts a new PLC record into the `PLC_INFO` table.
3. `UpdatePLC(PLC plc)`: Updates an existing PLC record in the `PLC_INFO` table based on the `INDEX_KEY`.
4. `DeletePLC(int indexKey)`: Deletes a PLC record from the `PLC_INFO` table based on the `INDEX_KEY`.

You can use these methods to manage your `PLC_LIST`. Whenever you modify or delete a PLC object in your list, make sure to call the corresponding method to update the `PLC_INFO` table in your MariaDB database.

