function swapSubpixels(imageData, pixelIndex, subpixel1, subpixel2) {
  const index1 = pixelIndex * 4 + subpixel1;
  const index2 = pixelIndex * 4 + subpixel2;

  const temp = imageData.data[index1];
  imageData.data[index1] = imageData.data[index2];
  imageData.data[index2] = temp;
}

