Unfortunately, it's not possible to write a single cross-platform C++ code to retrieve the local network gateway IP without using any external libraries, just the STL, since the Standard Library doesn't have native support for networking.

To achieve this, you will need to use platform-specific APIs to access the network information on each platform. On Linux and macOS, you can use the `getifaddrs()` function, while on Windows, you can use the `GetAdaptersInfo()` function.

Here's an example of how you could write a C++ program that works on Linux, macOS, and Windows using preprocessor directives to handle the platform-specific code. Note that this code requires linking to the `iphlpapi.lib` library on Windows, which is not an external library but a part of the Windows SDK.
```cpp
#include <iostream>
#include <string>

#if defined(_WIN32)
#include <winsock2.h>
#include <iphlpapi.h>
#pragma comment(lib, "iphlpapi.lib")

std::string get_gateway_ip() {
    std::string gateway_ip;
    IP_ADAPTER_INFO adapter_info[16];
    DWORD buf_len = sizeof(adapter_info);

    DWORD status = GetAdaptersInfo(adapter_info, &buf_len);
    if (status == ERROR_SUCCESS) {
        PIP_ADAPTER_INFO adapter = adapter_info;
        gateway_ip = adapter->GatewayList.IpAddress.String;
    }
    return gateway_ip;
}

#elif defined(__unix__) || defined(__APPLE__)
#include <sys/types.h>
#include <ifaddrs.h>
#include <netinet/in.h>
#include <arpa/inet.h>

std::string get_gateway_ip() {
    struct ifaddrs *ifaddr, *ifa;
    char gateway_ip[INET_ADDRSTRLEN] = {0};

    if (getifaddrs(&ifaddr) == -1) {
        perror("getifaddrs");
        return "";
    }

    for (ifa = ifaddr; ifa != nullptr; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == nullptr) {
            continue;
        }

        if ((ifa->ifa_flags & IFF_UP) && (ifa->ifa_flags & IFF_RUNNING) && !(ifa->ifa_flags & IFF_LOOPBACK)) {
            if (ifa->ifa_addr->sa_family == AF_INET) {
                void* tmp_addr_ptr = &((struct sockaddr_in *) ifa->ifa_addr)->sin_addr;
                inet_ntop(AF_INET, tmp_addr_ptr, gateway_ip, sizeof(gateway_ip));
                break;
            }
        }
    }
    freeifaddrs(ifaddr);
    return gateway_ip;
}

#endif

int main() {
    std::string gateway_ip = get_gateway_ip();
    if (!gateway_ip.empty()) {
        std::cout << "Gateway IP: " << gateway_ip << std::endl;
    } else {
        std::cout << "Unable to retrieve gateway IP" << std::endl;
    }
    return 0;
}
```
