                } else {
                    tmp_addr_ptr = &((struct sockaddr_in6 *) ifa->ifa_addr)->sin6_addr;
                }
                inet_ntop(family, tmp_addr_ptr, gateway_ip, sizeof(gateway_ip));
                break;
            }
        }
    }
    freeifaddrs(ifaddr);
    return gateway_ip;
}

#endif

int main() {
    std::string gateway_ip = get_gateway_ip();
    if (!gateway_ip.empty()) {
        std::cout << "Gateway IP: " << gateway_ip << std::endl;
    } else {
