    float shadowIntensity = clamp((lightFraction * distanceToLight + lightRadius) / (2.0 * lightRadius), 0.0, 1.0);
    shadowIntensity = smoothstep(0.0, 1.0, shadowIntensity);

    return shadowIntensity;
}
