```javascript
function getPermutations(arr, size) {
    const result = [];

    function permute(list, m = []) {
        if (list.length === 0) {
            result.push(m);
        } else {
            for (let i = 0; i < list.length; i++) {
                const curr = list.slice();
                const next = curr.splice(i, 1);
                permute(curr.slice(), m.concat(next));
            }
        }
    }

    permute(arr, []);

    return result.filter(p => p.length === size);
}

