Here's Python code using the Newton-Raphson method to numerically estimate the inverse of the function f(x) = exp(x) * sqrt(x) for a given value of y:

```python
import math

def f(x):
    return math.exp(x) * math.sqrt(x)

def df(x):
    return math.exp(x) * (0.5 * x**(-0.5) + math.sqrt(x))

def newton_raphson(y, x0=1, tol=1e-8, max_iter=100):
    x = x0
    for _ in range(max_iter):
        x_new = x - (f(x) - y) / df(x)
        if abs(x_new - x) < tol:
            return x_new
        x = x_new
    return None

y_value = 10  # Change this value to the desired y_value
inverse = newton_raphson(y_value)
if inverse is not None:
    print(f"The inverse of the function for y = {y_value} is approximately: {inverse}")
else:
    print("Unable to find the inverse of the function.")
```

