const md5 = async (data) => {
  // Check if in Node.js environment
  if (typeof process !== 'undefined' && process.versions && process.versions.node) {
    const crypto = require('crypto');
    const hash = crypto.createHash('md5');
    hash.update(data);
    return hash.digest('hex');
  }

  // Check if WebCrypto is available
  if (typeof window !== 'undefined' && window.crypto && window.crypto.subtle) {
    const encoder = new TextEncoder();
    const dataBuffer = encoder.encode(data);
    const digestBuffer = await window.crypto.subtle.digest('MD5', dataBuffer);
    const digestArray = new Uint8Array(digestBuffer);
    const digestHex = Array.from(digestArray).map(b => b.toString(16).padStart(2, '0')).join('');
    return digestHex;
  }

  // Fallback to TweetNaCl
  const nacl = require('tweetnacl');
  const blake2 = require('blakejs');

  // MD5 is not supported by TweetNaCl, so use blake2b as an alternative
  const encoder = new TextEncoder();
  const dataBuffer = encoder.encode(data);
  const digestBuffer = blake2.blake2b(dataBuffer, null, 16);
  const digestHex = Array.from(digestBuffer).map(b => b.toString(16).padStart(2, '0')).join('');
  return digestHex;
};

